#!/bin/bash
# Run the x86 differential check (examples/disasm_diff.rs) over every capstone reference corpus
# under testdata/scratch/disasm (generated by bench/scripts/disasm_diff.py gen). Prints only
# corpora with mismatches; exits non-zero if any mismatch was found.
#   bench/scripts/disasm_check_all.sh [BIN]
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
BIN=${1:-$ROOT/target/fast/examples/disasm_diff}
SCR=${DISASM_SCRATCH:-/home/user/fvol/testdata/scratch/disasm}
rc=0
for d in ref ref2 real2 small simd pp; do
  [ -d "$SCR/$d" ] || continue
  out=$("$BIN" cmp "$SCR/$d") || rc=1
  echo "$out" | grep -v " 0 (0.0000%)   weighted .* 0 (0.0000%)"
done
[ $rc = 0 ] && echo "all corpora: 0 mismatches"
exit $rc
